import React from 'react';
import {
  Alert,
  Box,
  Button,
  Stack,
  Typography,
} from '@mui/material';
import ArrowForwardIcon from '@mui/icons-material/ArrowForward';
import { Link as RouterLink } from 'react-router-dom';
import type { ApplicationWarning } from '../../hooks/useWarningResolution';
import {
  remediationActionLabelForBlockedReason,
  remediationLinkForBlockedReason,
} from '../../constants/reportingUxLabels';
import { DOCUMENT_UPLOAD_PATH } from '../../constants/documentRoutes';

type ApplicationWarningResolverProps = {
  warnings: ApplicationWarning[];
  period?: string;
  documentId?: string;
  onResolved?: () => void;
  compact?: boolean;
  showManualActions?: boolean;
};

const resolveManualLink = (warning: ApplicationWarning): string | null => {
  if (warning.hubLink) {
    return warning.hubLink;
  }
  const type = String(warning.type || '').toLowerCase();
  if (type.includes('ocr') || type.includes('document')) {
    return DOCUMENT_UPLOAD_PATH;
  }
  if (type.includes('spend_proxy') || type.includes('tier1') || type.includes('inventory_quality')) {
    return '/data?section=connectors';
  }
  if (type.includes('assurance') || type.includes('iso')) {
    return '/compliance/india?section=iso-assurance';
  }
  if (type.includes('cbam') || type.includes('export')) {
    return '/compliance/export?section=cbam';
  }
  const message = warning.message || warning.action || warning.detail || '';
  return remediationLinkForBlockedReason(message);
};

const resolveManualLabel = (warning: ApplicationWarning, fallbackMessage: string): string => {
  if (warning.action) {
    return warning.action;
  }
  const message = warning.message || warning.detail || fallbackMessage;
  return remediationActionLabelForBlockedReason(message);
};

/**
 * Manual remediation CTAs for application warnings / readiness gaps.
 * AI auto-resolve is not offered — gap fixes are not user-specific.
 */
const ApplicationWarningResolver: React.FC<ApplicationWarningResolverProps> = ({
  warnings,
  compact = false,
  showManualActions = true,
}) => {
  if (!warnings.length) {
    return null;
  }

  const primaryWarning = warnings[0];
  const manualLink = showManualActions ? resolveManualLink(primaryWarning) : null;
  const manualLabel = resolveManualLabel(primaryWarning, 'Fix manually');

  if (!manualLink) {
    return null;
  }

  if (compact) {
    return (
      <Box sx={{ mt: 1 }}>
        <Stack direction="row" spacing={1} flexWrap="wrap" useFlexGap>
          <Button
            size="small"
            variant="contained"
            component={RouterLink}
            to={manualLink}
            endIcon={<ArrowForwardIcon />}
          >
            {manualLabel}
          </Button>
        </Stack>
      </Box>
    );
  }

  return (
    <Alert
      severity="warning"
      sx={{ mb: 2 }}
      action={(
        <Button
          color="inherit"
          size="small"
          component={RouterLink}
          to={manualLink}
        >
          {manualLabel}
        </Button>
      )}
    >
      <Typography variant="subtitle2" gutterBottom>
        {warnings.length === 1 ? 'Issue detected' : `${warnings.length} issues detected`}
      </Typography>
      <Stack spacing={0.25}>
        {warnings.slice(0, 3).map((warning) => (
          <Typography key={warning.message || warning.action || warning.type} variant="body2">
            • {warning.message || warning.action || warning.detail}
          </Typography>
        ))}
      </Stack>
    </Alert>
  );
};

export default ApplicationWarningResolver;
